import { IsEmail, IsString, Length } from 'class-validator';

/**
 * Data Transfer Object (DTO) for Multi-Factor Authentication (MFA/TOTP) Confirmation
 * * Validates incoming request payloads when a user attempts to verify a 2FA/TOTP 
 * challenge during login or sensitive operations.
 */
export class ConfirmMfaDto {

    /**
     * Target user's primary email address.
     * * Must be a valid email format (e.g., user@example.com).
     */
    @IsEmail()
    email!: string;

    /**
     * The 6-digit Time-based One-Time Password (TOTP) generated by the user's authenticator app 
     * (e.g., Google Authenticator, Authy, 1Password).
     * * Must be a string with an exact length of 6 characters.
     */
    @IsString()
    @Length(6, 6)
    totpCode!: string;

}